{"hypotheses": [
  {
    "name": "Resilient Profitability-Momentum",
    "mechanism": "Combining OperProf, Mom12m, and IdioVol3F targets stocks with both strong profitability and momentum, while shorting idiosyncratic risk. This composite is expected to outperform its components because profitable firms with momentum and low idiosyncratic volatility are more resilient to market shocks, leading to a more persistent premium.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "IdioVol3F"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Contrarian Asset Growth-Illiquidity",
    "mechanism": "AssetGrowth and Illiquidity are both known return predictors, but their signals often conflict. By taking the difference, this composite captures the contrarian effect where low asset growth combined with high illiquidity earns a premium, exploiting overlooked deep value opportunities.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "Illiquidity"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Earnings Momentum and Analyst Disagreement",
    "mechanism": "Combining EarningsSurprise, Mom6m, and ForecastDispersion exploits the tendency for positive earnings surprises accompanied by momentum and high analyst disagreement to be underpriced, as the market is slower to reflect dispersed analyst opinion in prices.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 1.0, "primitive": "Mom6m"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom6m", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Quality Value in Low Beta",
    "mechanism": "By combining BM, OperProf, and a negative Beta exposure, this composite seeks high-quality value stocks with low market risk. The mechanism is that quality value stocks with lower beta avoid cyclical drawdowns, making the combined signal more robust to macro shocks than value or quality alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": -0.5, "primitive": "Beta"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Seasonal Sentiment Dispersion",
    "mechanism": "This composite blends MomSeason, AnalystRevision, and ForecastDispersion, capturing the effect where seasonal momentum is stronger for stocks with recent analyst upgrades and greater analyst disagreement, reflecting delayed incorporation of sentiment into prices.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomSeason"},
        {"weight": 0.5, "primitive": "AnalystRevision"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Defensive Franchises",
    "mechanism": "Combining BrandInvest and Cash with a negative loading on RealizedVol, the composite identifies firms with strong brand capital, high cash reserves, and low realized volatility. This focuses on defensive franchises with superior downside protection in risk-off regimes, offering a premium from stability and intangible capital.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 0.5, "primitive": "Cash"},
        {"weight": -0.5, "primitive": "RealizedVol"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "BrandInvest", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Capital Discipline in High Uncertainty",
    "mechanism": "This composite combines negative NetEquityFinance, positive ShareRepurchase, and positive RD to exploit periods when disciplined capital management (repurchases, limited new equity, robust R&D) is most rewarded, especially in volatile environments where capital discipline signals management quality.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "NetEquityFinance"},
        {"weight": 1.0, "primitive": "ShareRepurchase"},
        {"weight": 0.5, "primitive": "RD"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "international", "region": "emerging", "direction": "opposite_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Overlooked Innovators",
    "mechanism": "The composite adds SurpriseRD, PatentsRD, and subtracts AnalystValue, focusing on firms with unexpected R&D increases and strong patent output but low analyst endorsement. This exploits the lag in consensus recognizing innovative firms, leading to persistent mispricing.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "SurpriseRD"},
        {"weight": 1.0, "primitive": "PatentsRD"},
        {"weight": -1.0, "primitive": "AnalystValue"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "PatentsRD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 36
  }
]}
